'use strict';

/* ------------------------------------------------------------------ reveal */

(function () {
  if (!('IntersectionObserver' in window)) {
    document.querySelectorAll('.animate').forEach(function (el) {
      el.classList.remove('animate');
    });
    return;
  }

  var revealObserver = new IntersectionObserver(function (entries) {
    entries.forEach(function (entry) {
      if (!entry.isIntersecting) return;
      entry.target.classList.add(entry.target.getAttribute('data-animation'));
      entry.target.classList.remove('animate');
      revealObserver.unobserve(entry.target);
    });
  }, { rootMargin: '0px 0px -8% 0px' });

  document.querySelectorAll('.animate').forEach(function (el) {
    revealObserver.observe(el);
  });
})();

/* ------------------------------------------------------------- nav + scroll */

(function () {
  var nav = document.getElementById('topnav');

  if (nav) {
    var onScroll = function () {
      nav.classList.toggle('topnav--solid', window.scrollY > 40);
    };
    onScroll();
    window.addEventListener('scroll', onScroll, { passive: true });
  }

  // highlight the section currently in view
  var links = Array.prototype.slice.call(document.querySelectorAll('.topnav__links a'));
  var sections = links
    .map(function (a) { return document.querySelector(a.getAttribute('href')); })
    .filter(Boolean);

  if ('IntersectionObserver' in window && sections.length) {
    var spy = new IntersectionObserver(function (entries) {
      entries.forEach(function (entry) {
        if (!entry.isIntersecting) return;
        links.forEach(function (a) {
          a.classList.toggle('is-active', a.getAttribute('href') === '#' + entry.target.id);
        });
      });
    }, { rootMargin: '-45% 0px -50% 0px' });

    sections.forEach(function (s) { spy.observe(s); });
  }
})();

/* -------------------------------------------------------------- project tabs */

(function () {
  var buttons = document.querySelectorAll('.category-btn');
  var panels = document.querySelectorAll('.project-category-container');
  if (!buttons.length) return;

  buttons.forEach(function (btn) {
    btn.addEventListener('click', function () {
      var target = document.getElementById(btn.getAttribute('data-category') + '-container');
      if (!target) return;

      buttons.forEach(function (b) {
        var on = b === btn;
        b.classList.toggle('active', on);
        b.setAttribute('aria-selected', on ? 'true' : 'false');
      });

      panels.forEach(function (p) { p.classList.remove('active'); });
      target.classList.add('active');

      // replay the entrance animation for cards revealed for the first time
      target.querySelectorAll('.animate').forEach(function (el) {
        el.classList.add(el.getAttribute('data-animation'));
        el.classList.remove('animate');
      });
    });
  });
})();

/* ------------------------------------------------------------ contact form */

(function () {
  var form = document.getElementById('contact-form');
  var notification = document.getElementById('notification');
  if (!form) return;

  var noteIcon = notification && notification.querySelector('.notification-content i');
  var noteText = notification && notification.querySelector('.notification-content p');
  var noteBox = notification && notification.querySelector('.notification-content');
  var button = form.querySelector('.submit-btn');
  var buttonHTML = button ? button.innerHTML : '';

  function notify(message, ok) {
    if (!notification) { alert(message); return; }

    if (noteText) noteText.textContent = message;
    if (noteIcon) noteIcon.className = ok ? 'fas fa-check-circle' : 'fas fa-triangle-exclamation';
    if (noteBox) noteBox.classList.toggle('is-error', !ok);

    notification.classList.add('active');
    window.setTimeout(function () {
      notification.classList.remove('active');
    }, 4000);
  }

  if (notification) {
    notification.addEventListener('click', function () {
      notification.classList.remove('active');
    });
  }

  form.addEventListener('submit', function (e) {
    e.preventDefault();

    if (button) {
      button.disabled = true;
      button.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Sending...';
    }

    fetch(form.action, {
      method: 'POST',
      headers: { Accept: 'application/json' },
      body: new FormData(form)
    })
      .then(function (res) {
        return res.json().then(function (data) { return { ok: res.ok, data: data }; });
      })
      .then(function (result) {
        if (result.ok && result.data.success) {
          form.reset();
          notify('Message Sent Successfully!', true);
        } else {
          notify(result.data.message || 'Something went wrong. Please email me directly.', false);
        }
      })
      .catch(function () {
        notify('Network error. Please email me directly.', false);
      })
      .then(function () {
        if (button) {
          button.disabled = false;
          button.innerHTML = buttonHTML;
        }
      });
  });
})();

/* -------------------------------------------------------------------- misc */

(function () {
  var year = document.getElementById('year');
  if (year) year.textContent = new Date().getFullYear();
})();
